import type { z } from 'zod';
import type { dungeonLootInput, gearCandidatesInput } from '../contract/game-inspection.ts';
import type { InspectionResult } from '../contract/game-inspection-results.ts';
import generated from './dungeon-loot.json' with { type: 'json' };

// Boss loot generated by packages/game-data from the pinned AtlasLoot
// Classic Forever release (pnpm data:generate). Item IDs only: names, stats
// and the comparison with current gear come from the game.
interface LootItem {
  id: number;
  chance?: number;
  forever?: boolean;
}
interface LootBoss {
  name: string;
  npcIds?: number[];
  extra?: boolean;
  noDropsYet?: boolean;
  items: LootItem[];
}
interface LootInstance {
  key: string;
  name: string;
  instanceMapId?: number;
  kind: string;
  forever?: boolean;
  levels?: { min: number; recommended: number; max: number };
  bosses: LootBoss[];
}
interface LootData {
  generated: { note: string };
  data: { instances: LootInstance[] };
}

// The game reads at most this many items per call.
const MAX_ITEMS = 500;
// Full detail larger than this (about 10k tokens) falls back to the summary.
const MAX_FULL_CHARS = 40_000;
function positive(value: unknown): value is number {
  return typeof value === 'number' && value > 0;
}

const NOTE =
  'Bosses list their drops in AtlasLoot order. source: boss (a boss table), trash (trash mobs), shared (drops from several bosses, kept when filtering by boss; its name says which), other (rare or summoned bosses, chests, quest rewards and similar). statDelta and itemLevelGain compare equipment with the weakest equipped item for its slot. proficiency: usable now, trainable (the class learns that weapon or armor skill at a trainer from trainableAtLevel), class_cannot_use; hiddenUnusable counts items this class can never use (includeUnusable lists them). summary lists every drop with its name, drop chance, required level and, when it beats current gear, itemLevelGain and statDelta (proficiency only when not usable); full adds the stats of every item and the equipped item, for one boss. unread items were not read from the game (too many, or not cached yet).';

function fold(text: string) {
  return text
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/^the /, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const TRASH = /^trash( mobs)?$/i;
// Lists such as Zul'Gurub's "High Priest Shared loot" or Molten Core's
// "All bosses" drop from several bosses.
function shared(entry: LootBoss) {
  return Boolean(entry.extra) && /\bshared\b|^all bosses$/i.test(entry.name);
}

function compact(text: string) {
  return text.replaceAll(' ', '');
}

type GearReading = InspectionResult<'gear_candidates'>;
type GameItem = Extract<GearReading, { status: 'available' }>['data']['items'][number] & {
  chance?: number;
  addedInForever?: boolean;
  unread?: boolean;
};

export interface LootBossResult {
  name: string;
  npcIds?: number[];
  source: 'boss' | 'trash' | 'shared' | 'other';
  noDropsYet?: boolean;
  hiddenUnusable?: number;
  // full
  items?: GameItem[];
  // summary
  upgradeCount?: number;
}
export interface LootResult {
  status: string;
  error?: string;
  detail?: 'summary' | 'full';
  source: { name: string; note: string; chance: string };
  instances?: {
    name: string;
    instanceMapId?: number;
    kind: string;
    forever?: boolean;
    levels?: { min: number; recommended: number; max: number };
    bosses: LootBossResult[];
  }[];
  loadingIds?: number[];
  unreadItems?: number;
  truncated?: string;
  note?: string;
}

// The instances and bosses that match, each item joined with the game's
// reading of it: name, quality, levels, stats and, for equipment, the change
// against the weakest equipped item in its slot.
export async function dungeonLoot(
  args: z.infer<typeof dungeonLootInput>,
  readGame: (inspection: {
    kind: 'gear_candidates';
    args: z.input<typeof gearCandidatesInput>;
  }) => Promise<GearReading>,
  data: LootData = generated as LootData,
): Promise<LootResult> {
  const wanted = args.dungeon ? fold(args.dungeon) : undefined;
  const boss = args.boss ? fold(args.boss) : undefined;
  const named = data.data.instances.filter((instance) =>
    args.instanceMapId !== undefined
      ? instance.instanceMapId === args.instanceMapId
      : // Word breaks are ignored: AtlasLoot keys run words together
        // ("TheTempleOfAtal'Hakkar").
        [instance.name, instance.key].some((name) =>
          compact(fold(name)).includes(compact(wanted!)),
        ),
  );
  // A name can match only an empty table of an instance whose loot sits
  // under another name ("Onyxias Lair" is empty; "Onyxia" has the drops):
  // add the other tables of that instance map.
  const emptyMaps = new Set(
    named
      .filter((instance) => !instance.bosses.some((entry) => entry.items.length))
      .map((instance) => instance.instanceMapId)
      .filter((id) => id !== undefined),
  );
  const instances = data.data.instances
    .filter(
      (instance) =>
        named.includes(instance) ||
        (instance.instanceMapId !== undefined && emptyMaps.has(instance.instanceMapId)),
    )
    .map((instance) => ({
      ...instance,
      // Loot shared by several bosses stays next to the one asked for.
      bosses: instance.bosses.filter(
        (entry) => !boss || fold(entry.name).includes(boss) || shared(entry),
      ),
    }));
  const source = {
    name: 'AtlasLoot Classic Forever',
    note: data.generated.note,
    chance: 'Drop chance in percent from AtlasLoot, classic-era rates; missing means not known.',
  };
  if (!instances.length) {
    return {
      status: 'unavailable',
      error: 'No dungeon or raid loot matches; use instanceMapId from wow__query_dungeons.',
      source,
    };
  }
  const ids = [
    ...new Set(instances.flatMap((i) => i.bosses.flatMap((b) => b.items.map((item) => item.id)))),
  ];
  const read = ids.slice(0, MAX_ITEMS);
  // The addon answers { status, data, error }; data holds the gear reading.
  const envelope: GearReading = read.length
    ? await readGame({
        kind: 'gear_candidates',
        args: { itemIds: read, minRequiredLevel: 0, maxRequiredLevel: 100, includeOther: true },
      })
    : { status: 'available', data: { items: [] } };
  if (envelope.status === 'unavailable') {
    return {
      status: envelope.status,
      error: envelope.error,
      source,
    };
  }
  const reading = envelope.data;
  const known = new Map<number, GameItem>();
  for (const item of [...reading.items, ...(reading.other ?? [])]) {
    known.set(item.id, item);
  }
  const detail = args.detail ?? (args.boss ? 'full' : 'summary');
  const bosses = (instance: LootInstance, level: 'summary' | 'full'): LootBossResult[] =>
    instance.bosses.map((entry) => {
      const items = entry.items.map((item) => {
        const game = known.get(item.id);
        return {
          ...(game ?? { id: item.id }),
          chance: item.chance,
          addedInForever: item.forever,
          ...(game ? {} : { unread: true }),
        };
      });
      const shown = args.includeUnusable
        ? items
        : items.filter((item) => item.proficiency !== 'class_cannot_use');
      const hiddenUnusable = items.length - shown.length || undefined;
      const heading: LootBossResult = {
        name: entry.name,
        npcIds: entry.npcIds,
        // AtlasLoot's extra lists hold trash, shared loot, rare or
        // summoned bosses, chests and quest rewards; only trash is trash.
        source: !entry.extra
          ? 'boss'
          : TRASH.test(entry.name)
            ? 'trash'
            : shared(entry)
              ? 'shared'
              : 'other',
        noDropsYet: entry.noDropsYet,
        hiddenUnusable,
      };
      if (level === 'full') {
        return { ...heading, items: shown };
      }
      // Every drop in a few fields: enough to name what each boss drops and
      // spot upgrades, without stats and comparisons.
      return {
        ...heading,
        upgradeCount: shown.filter((item) => positive(item.itemLevelGain)).length,
        items: shown.map((item) => ({
          id: item.id,
          name: item.name,
          chance: item.chance,
          requiredLevel: item.requiredLevel,
          itemLevelGain: positive(item.itemLevelGain) ? item.itemLevelGain : undefined,
          // Upgrades carry what they change, so the answer needs no full read.
          statDelta: positive(item.itemLevelGain) ? item.statDelta : undefined,
          proficiency: item.proficiency === 'usable' ? undefined : item.proficiency,
          trainableAtLevel: item.trainableAtLevel,
          addedInForever: item.addedInForever,
          unread: item.unread,
        })),
      };
    });
  const result = (level: 'summary' | 'full'): LootResult => ({
    status: reading.status === 'loading' ? 'loading' : 'available',
    detail: level,
    source,
    instances: instances.map((instance) => ({
      name: instance.name,
      instanceMapId: instance.instanceMapId,
      kind: instance.kind,
      forever: instance.forever,
      levels: instance.levels,
      bosses: bosses(instance, level),
    })),
    loadingIds: reading.loadingIds ? [...reading.loadingIds] : undefined,
    unreadItems: ids.length > MAX_ITEMS ? ids.length - MAX_ITEMS : undefined,
    note: NOTE,
  });
  const full = result(detail);
  if (detail === 'full' && JSON.stringify(full).length > MAX_FULL_CHARS) {
    return {
      ...result('summary'),
      truncated:
        'Too many items for full detail; this is the summary. Ask again with boss for full detail.',
    };
  }
  return full;
}
